('Each call sign is a row: pick the member for it.', 'nr', 'Ibizo ngalinye lokubizana mugqa: khetha ilunga lalo.'),
('Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.', 'nr', 'Ibizo ngalinye lokubizana yindawo yomsebenzi yinye: lapho ligada khona, amahora walo, ikhefu lalo nesikhundla elisitlhogako. I-Duty Allocation ibhukela abasebenzi kilezo.'),
