('I checked this ambulance and its stock myself, and the answers above are accurate.', 'nr', 'Ngiyihlolile i-ambulensi le neempahla zayo ngokwami, begodu iimpendulo ezingehla zilungile.'),
('I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.', 'nr', 'Ngiyaqinisekisa bona ngiyihlolile ikoloyi engehla ngamehlo begodu bona ilwazi elitloliweko lilungile ngokwalokho engikwaziko. Nanyana ngimaphi amaphoso abonakeleko kufanele abikwe kumphathi msinyana begodu atlolwe encwadini yepokethe esemthethweni.'),
