('I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).', 'nr', 'Ngihlathulule isaziso nemikhetho: bhadala ngamalanga ama-32 bona uthole isaphulelo, bawa ukubhadala ngeengcenye (AARTO 04), namkha wenze isibawo sokuzivikela (AARTO 08).'),
