('I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.', 'nr', 'Ngiyazi bona umnyango wakho usebenza njani begodu ngingafunda ibhodi ephilako isikhundla sakho esiyibonako. Ngibuze nanyana yini, namkha ungitjele bona ngenzeni. Ngiyakulungiselela, begodu akukho okutjhugulukako bekube uyaqinisekisa.'),
('I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.', 'nr', 'Ngiyayazi ishifu yakho, iifowuni zakho, amalanga wakho wokuphumula neempahla zakho zomsebenzi. Ngibuze nanyana yini ngomsebenzi wakho, ngamezwi wakho. Ngiyahlathulula begodu ngikutjengise lapho kufanele uye khona; wena wenza umsebenzi.'),
