('Secrets live in server environment variables and are never stored in the database or sent to the browser — this page only reports whether each one is present. The switch and the JSON parameters below are stored in the database and take effect immediately, with no redeploy. Adding or changing a secret requires setting it on the host and redeploying.', 'nr', 'Iimfihlo zigcinwa eenzintweni ezitjhugulukako zobujamo beseva begodu azikhe zigcinwe ku-database namkha zithunyelwe esiphequluli — ikhasi leli libika kwaphela bona ngayinye ikhona na. Iswitjhi namapharamitha we-JSON angenzasi agcinwa ku-database begodu asebenza msinyana, ngaphandle kokufaka godu. Ukwengeza namkha ukutjhugulula imfihlo kutlhoga ukuyibeka kumsingathi bese ufaka godu.'),
